from playwright.sync_api import sync_playwright
import datetime
def ok(n,c): print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as p:
    b=p.chromium.launch()
    for sch in ('light','dark'):
        c=b.new_context(service_workers='block',viewport={'width':390,'height':844},color_scheme=sch); pg=c.new_page(); errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
        pg.clock.set_fixed_time(datetime.datetime(2026,10,22,12,0,0))
        pg.goto('http://localhost:8123/'); pg.wait_for_selector('#first-file',state='attached'); pg.set_input_files('#first-file','/home/claude/Transactions.csv'); pg.wait_for_selector('#setup',timeout=20000)
        pg.goto('http://localhost:8123/#/home'); pg.wait_for_timeout(1800)
        n=sch+': '
        w=pg.evaluate("(()=>{const wb=document.querySelector('.week .wc .wb'),i=wb.querySelector('i'),s=getComputedStyle(i),cell=wb.closest('.wc').getBoundingClientRect().width,v=document.querySelector('.week .wkv'),g=getComputedStyle(v,'::before');return {bw:wb.getBoundingClientRect().width,cell,bg:s.backgroundImage.includes('gradient'),rad:s.borderTopLeftRadius,shadow:s.boxShadow,track:getComputedStyle(wb).backgroundImage+getComputedStyle(wb).backgroundColor,grid:(g.backgroundImage.match(/linear-gradient/g)||[]).length,inline:[...document.querySelectorAll('.week .wc .wb i')].some(e=>/background:/.test(e.getAttribute('style')))}})()")
        print(w)
        ok(n+'bars narrower (<=22px, under half of the cell)', w['bw']<=22.5 and w['bw']<w['cell']*.5)
        ok(n+'bars use a vertical gradient with rounded tops', w['bg'] and w['rad']=='12px' and not w['inline'])
        ok(n+'no empty slot behind the bars', w['track'].replace(' ','') in ('nonergba(0,0,0,0)','rgba(0,0,0,0)none') or 'none' in w['track'] and 'rgba(0, 0, 0, 0)' in w['track'])
        ok(n+'outward shadow (not inset)', 'inset' not in w['shadow'] and w['shadow']!='none')
        ok(n+'three gridlines', w['grid']==3)
        cols=pg.evaluate("[...document.querySelectorAll('.week .wc .wb i')].map(e=>e.style.getPropertyValue('--bc'))")
        ok(n+'red/green indicators kept %s'%cols, any(int(x.split()[0][4:])<10 for x in cols if x) and any(int(x.split()[0][4:])>100 for x in cols if x))
        f=pg.evaluate("(()=>({op:[...document.querySelectorAll('.main-home-card .sc-front stop')].map(s=>s.getAttribute('stop-opacity')),line:getComputedStyle(document.querySelector('.main-home-card .sk-line')).opacity}))()")
        ok(n+'home fill strong at the line, 0 at bottom, line nearly invisible %s'%f, float(f['op'][0])>=.45 and float(f['op'][-1])==0 and float(f['line'])<=.3)
        pg.goto('http://localhost:8123/#/analytics'); pg.wait_for_timeout(1200)
        f=pg.evaluate("(()=>({op:[...document.querySelector('svg.t1line').querySelectorAll('stop')].map(s=>s.getAttribute('stop-opacity')),line:getComputedStyle(document.querySelector('svg.t1line .t1l')).opacity}))()")
        ok(n+'analytics fill and line match', float(f['op'][0])>=.45 and float(f['op'][-1])==0 and float(f['line'])<=.3)
        ok(n+'no errors %s'%errs, not errs)
        c.close()
    c=b.new_context(service_workers='block',viewport={'width':390,'height':844}); pg=c.new_page(); pg.clock.set_fixed_time(datetime.datetime(2026,10,22,12,0,0))
    pg.goto('http://localhost:8123/'); pg.wait_for_selector('#first-file',state='attached'); pg.set_input_files('#first-file','/home/claude/Transactions.csv'); pg.wait_for_selector('#setup',timeout=20000)
    pg.evaluate("localStorage.setItem('sukli-look', JSON.stringify({design:'legacy'}))"); pg.reload(); pg.wait_for_timeout(1500)
    ok('legacy bars keep their solid colour and track', pg.evaluate("(()=>{const i=document.querySelector('.week .wc .wb i');return /background:/.test(i.getAttribute('style'))&&!getComputedStyle(i).backgroundImage.includes('gradient')})()"))
